exports.init = (params, rng) => {
  const N=5;
  const blocks=[];
  for(let i=0;i<N;i++){
    blocks.push({
      id:i,
      x: rng.range(1.5,8.5),
      y: rng.range(6.5,9),
      vy:0,
      h:1,
      w:1,
      submergedFrac:0,
      buoyant:0,
      weight:0
    });
  }
  return {
    blocks,
    waterLevel:5,
    iceDensity: params.iceDensity ?? 0.917,
    waterDensity: params.waterDensity ?? 1,
    hasAirBubbles: params.hasAirBubbles ?? false,
    time:0
  };
};
exports.step = (state, params, rng) => {
  const dt=0.05;
  const g=9.8;
  const drag=3.5;
  const iceDensity = params.iceDensity ?? state.iceDensity;
  const waterDensity = params.waterDensity ?? state.waterDensity;
  const hasAirBubbles = params.hasAirBubbles ?? state.hasAirBubbles;
  const effectiveDensity = iceDensity - (hasAirBubbles ? 0.05 : 0);
  const newBlocks = state.blocks.map(b=>{
    let y=b.y;
    let vy=b.vy;
    const h=b.h;
    const w=b.w;
    const volume=h*w*1;
    const mass=effectiveDensity*volume;
    const bottom=y-h/2;
    const top=y+h/2;
    let submergedH=0;
    if(bottom < state.waterLevel){
      if(top <= state.waterLevel) submergedH=h;
      else submergedH=state.waterLevel-bottom;
    }
    if(submergedH<0) submergedH=0;
    if(submergedH>h) submergedH=h;
    const submergedVol=submergedH*w*1;
    const buoyant=waterDensity*submergedVol*g;
    const weight=effectiveDensity*volume*g;
    let net=buoyant-weight-drag*vy;
    const ay=net/mass;
    vy+=ay*dt;
    if(vy>5) vy=5;
    if(vy<-5) vy=-5;
    y+=vy*dt;
    if(y-h/2 < 0){ y=h/2; vy=0; }
    if(y+h/2 > 10){ y=10-h/2; vy=0; }
    const bottom2=y-h/2;
    const top2=y+h/2;
    let submergedH2=0;
    if(bottom2 < state.waterLevel){
      if(top2 <= state.waterLevel) submergedH2=h;
      else submergedH2=state.waterLevel-bottom2;
    }
    if(submergedH2<0) submergedH2=0;
    if(submergedH2>h) submergedH2=h;
    return {
      id:b.id,
      x:b.x,
      y:y,
      vy:vy,
      h:h,
      w:w,
      submergedFrac:submergedH2/h,
      buoyant:waterDensity*submergedH2*w*g,
      weight:weight
    };
  });
  return {
    blocks:newBlocks,
    waterLevel:state.waterLevel,
    iceDensity:iceDensity,
    waterDensity:waterDensity,
    hasAirBubbles:hasAirBubbles,
    time:state.time+dt
  };
};
exports.observe = (state, params) => {
  const n=state.blocks.length;
  let floating=0;
  let sumSub=0;
  let sumRatio=0;
  for(const b of state.blocks){
    if(b.y > 1.0) floating+=1;
    sumSub+=b.submergedFrac;
    const ratio=b.weight>0 ? b.buoyant/b.weight : 0;
    sumRatio+=ratio;
  }
  return {
    fraction_floating: floating/n,
    submerged_volume_fraction: sumSub/n,
    buoyant_force_over_weight_ratio: sumRatio/n
  };
};
exports.view = (state, params) => {
  const bodies=[];
  const waterYView = 10 - state.waterLevel;
  for(let i=0;i<=10;i++){
    bodies.push({ id:`water-${i}`, x:i, y:waterYView, radius:0.14, color:"#4a9fe3" });
  }
  for(let i=0;i<=10;i++){
    bodies.push({ id:`bottom-${i}`, x:i, y:9.6, radius:0.08, color:"#2c3e50" });
  }
  state.blocks.forEach(b=>{
    const isSinking = b.y <= 1.2;
    let bob=0;
    if(!isSinking){
      bob = Math.sin(state.time*2.5 + b.id*1.3)*0.12;
    }
    const yView = 10 - b.y + bob;
    let color;
    if(isSinking){
      color="#1e3a5f";
    } else {
      const t = Math.max(0, Math.min(1, (b.submergedFrac-0.7)/0.3));
      const r = Math.round(200 - t*60);
      const g = Math.round(232 - t*40);
      const bcol = Math.round(255 - t*30);
      color = "#" + [r,g,bcol].map(v=>v.toString(16).padStart(2,"0")).join("");
    }
    const radius = isSinking ? 0.42 : 0.52 + b.submergedFrac*0.08;
    bodies.push({ id:String(b.id), x:b.x, y:yView, radius:radius, color:color });
    if(!isSinking){
      bodies.push({ id:`sub-${b.id}`, x:b.x, y:yView+0.18, radius:radius*0.55, color:"#6fb7e8" });
    }
  });
  return { kind:"bodies", bounds:{x:0,y:0,w:10,h:10}, bodies };
};
